/*
c = a ⋅ A
                where
                a: scalar
                A: ℝ ^ (2 × 2): a matrix
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::Matrix<DT, 2, 2> c;

    heartlib(
        const double & a,
        const Eigen::Matrix<double, 2, 2> & A)
    {

        // c = a ⋅ A
        c = a * A;
    }
};

