outputs.matlab:
function output = heartlib(a, A)
% output = heartlib(a, A)
%
%    c = a ⋅ A
%                    where
%                    a: scalar
%                    A: ℝ ^ (2 × 2): a matrix
    assert(numel(a) == 1);
    assert( isequal(size(A), [2, 2]) );

    % c = a ⋅ A

    c = a * A;
    output.c = c;
end

